import os
import requests

class AzureTranslatorClient:
    def __init__(self, api_key=None, region=None, endpoint="https://api.cognitive.microsofttranslator.com"):
        self.api_key = api_key or os.environ.get("AZURE_TRANSLATOR_API_KEY")
        self.region = region or os.environ.get("AZURE_TRANSLATOR_REGION")
        self.endpoint = endpoint
        if not self.api_key or not self.region:
            raise ValueError("Azure Translator API key and region must be provided or set as environment variables.")

    def translate_request(self, text_entries, from_lang, to_lang):
        headers = {
            'Ocp-Apim-Subscription-Key': self.api_key,
            'Ocp-Apim-Subscription-Region': self.region,
            'Content-type': 'application/json'
        }
        params = {
            'api-version': '3.0',
            'from': from_lang,
            'to': to_lang
        }
        body = [{'Text': entry} for entry in text_entries]

        response = requests.post(f"{self.endpoint}/translate", headers=headers, params=params, json=body, timeout=30)
        response.raise_for_status()
        return response.json()

from typing import List, Dict, Any

class TranslationRequest:
    def __init__(self, text: str, source_language: str, target_language: str):
        self.text = text
        self.source_language = source_language
        self.target_language = target_language

    def to_azure_input(self) -> List[Dict[str, str]]:
        return [{'Text': self.text}]

class BatchTranslationRequest:
    def __init__(self, texts: List[str], source_language: str, target_language: str):
        self.texts = texts
        self.source_language = source_language
        self.target_language = target_language

    def to_azure_input(self) -> List[Dict[str, str]]:
        return [{'Text': text} for text in self.texts]

class TranslationResponse:
    def __init__(self, azure_response: List[Dict[str, Any]], source_language: str, target_language: str):
        self.translated_text = azure_response[0]['translations'][0]['text'] if azure_response and azure_response[0].get('translations') else ""
        self.source_language = source_language
        self.target_language = target_language

class BatchTranslationResponse:
    def __init__(self, azure_response: List[Dict[str, Any]], source_language: str, target_language: str):
        self.translated_texts = [
            item['translations'][0]['text'] 
            for item in azure_response 
            if item.get('translations')
        ]
        self.source_language = source_language
        self.target_language = target_language

class MarkupTranslationRequest:
    def __init__(self, html_content: str, source_language: str, target_language: str):
        self.html_content = html_content
        self.source_language = source_language
        self.target_language = target_language

    def to_azure_input(self) -> List[Dict[str, str]]:
        return [{'Text': self.html_content}]

