from translation_client import AzureTranslatorClient
from translation_models import DictionaryTranslationRequest, BatchTranslationResponse
import os

def translate_dictionary_values(payload, config=None):
    config = config or {}
    client = AzureTranslatorClient(api_key=config.get('api_key'), region=config.get('region'))

    request_model = DictionaryTranslationRequest(
        dictionary=payload['dictionary'],
        source_language=payload['source_language'],
        target_language=payload['target_language']
    )

    original_keys = list(request_model.dictionary.keys())
    original_values = list(request_model.dictionary.values())

    if not original_values:
        return {
            'translated_dictionary': {},
            'source_language': request_model.source_language,
            'target_language': request_model.target_language
        }

    azure_response = client.translate_request(
        text_entries=request_model.to_azure_input(),
        from_lang=request_model.source_language,
        to_lang=request_model.target_language
    )

    response_model = BatchTranslationResponse(
        azure_response=azure_response,
        source_language=request_model.source_language,
        target_language=request_model.target_language
    )

    translated_dictionary = {original_keys[i]: response_model.translated_texts[i] 
                             for i in range(len(original_keys))}

    return {
        'translated_dictionary': translated_dictionary,
        'source_language': response_model.source_language,
        'target_language': response_model.target_language
    }

from googleapiclient import discovery
import json
import os

def check_unsafe_content(payload, config=None):
    config = config or {}

    # Initialize the Perspective API client
    # Ensure GOOGLE_API_KEY environment variable is set for API key authentication
    # Or pass it in config as 'api_key'
    api_key = config.get('api_key') or os.environ.get('PERSPECTIVE_API_KEY')
    if not api_key:
        raise ValueError("Perspective API key must be provided or set as PERSPECTIVE_API_KEY environment variable.")

    client = discovery.build(
        "commentanalyzer",
        "v1alpha1",
        developerKey=api_key,
        discoveryServiceUrl="https://commentanalyzer.googleapis.com/$discovery/rest?version=v1alpha1",
        static_discovery=False,
    )

    text_to_analyze = payload['localized_text']

    analyze_request = {
        'comment': { 'text': text_to_analyze },
        'requestedAttributes': { 'TOXICITY': {}, 'SEVERE_TOXICITY': {}, 'IDENTITY_ATTACK': {}, 'INSULT': {}, 'PROFANITY': {}, 'THREAT': {} }
    }

    response = client.comments().analyze(body=analyze_request).execute()

    attribute_scores = {}
    for attribute, data in response['attributeScores'].items():
        attribute_scores[attribute] = data['summaryScore']['value']

    # Determine if any attribute score indicates unsafe content (e.g., score > 0.5)
    is_unsafe = any(score > 0.5 for score in attribute_scores.values())

    return {
        'localized_text': text_to_analyze,
        'attribute_scores': attribute_scores,
        'is_unsafe': is_unsafe,
        'notes': "Scores range from 0 to 1, where higher values indicate a greater perceived likelihood of the attribute being true for the text."
    }
